34	bool SelectorEngine::IsOpSupported(HcclCMDType opType)
35	{
36	    // 本迭代新选择器仅支持 AllReduce/ReduceScatter/AllGather, 其他算子走老流程
37	    static const std::set<HcclCMDType> supportedOps = {
38	        HcclCMDType::HCCL_CMD_ALLREDUCE,
39	        HcclCMDType::HCCL_CMD_REDUCE_SCATTER,
40	        HcclCMDType::HCCL_CMD_ALLGATHER,
41	    };
42	    return supportedOps.count(opType) > 0;
43	}
