45	OpExecuteConfig SelectorEngine::GetEngineByAlgName(const std::string& algName)
46	{
47	    // 逆序遍历: 长前缀优先(CcuSched > CcuMS)
48	    for (auto it = ENGINE_PREFIX_MAP.rbegin(); it != ENGINE_PREFIX_MAP.rend(); ++it) {
49	        if (algName.rfind(it->first, 0) == 0) {
50	            return it->second;
51	        }
52	    }
53	    return OpExecuteConfig::AICPU_TS;
54	}
