56	std::vector<std::string> SelectorEngine::CandidateEnginesToPrefixes(const std::vector<OpExecuteConfig>& engines)
57	{
58	    std::set<OpExecuteConfig> engineSet(engines.begin(), engines.end());
59	    std::vector<std::string> prefixes;
60	    for (const auto& entry : ENGINE_PREFIX_MAP) {
61	        if (engineSet.count(entry.second) != 0) {
62	            prefixes.emplace_back(entry.first);
63	        }
64	    }
65	    return prefixes;
66	}
