68	std::vector<OpExecuteConfig>
69	SelectorEngine::GetEnginePriority(TopoInfoWithNetLayerDetails* topoInfo, OpExecuteConfig opExecuteConfig)
70	{
71	    // hostDpuOnly 已在 HcclCalcTopoInfo 中计算并缓存
72	    if (topoInfo != nullptr && topoInfo->hostDpuOnly) {
73	        HCCL_INFO("[GetEnginePriority] hostDpuOnly=true, return [HOSTCPU].");
74	        return {OpExecuteConfig::HOSTCPU};
75	    }
76	
77	    switch (opExecuteConfig) {
78	        case OpExecuteConfig::CCU_MS:
79	            // CCU_MS → CCU_SCHED → AICPU 回退链
80	            return {OpExecuteConfig::CCU_MS, OpExecuteConfig::CCU_SCHED, OpExecuteConfig::AICPU_TS};
81	        case OpExecuteConfig::CCU_SCHED:
82	            // CCU_SCHED → AICPU 回退链
83	            return {OpExecuteConfig::CCU_SCHED, OpExecuteConfig::AICPU_TS};
84	        case OpExecuteConfig::AIV:
85	            // AIV → AICPU 回退链
86	            return {OpExecuteConfig::AIV, OpExecuteConfig::AICPU_TS};
87	        case OpExecuteConfig::AIV_ONLY:
88	            // AIV only, 不回退
89	            return {OpExecuteConfig::AIV};
90	        case OpExecuteConfig::AICPU_TS:
91	            // AICPU only
92	            return {OpExecuteConfig::AICPU_TS};
93	        case OpExecuteConfig::HOSTCPU:
94	            // HOSTCPU(DPU)
95	            return {OpExecuteConfig::HOSTCPU};
96	        default:
97	            // 安全回退:仅 AICPU
98	            return {OpExecuteConfig::AICPU_TS};
99	    }
100	}
