102	HcclResult SelectorEngine::FilterCmByEngine(CostModel& cm, const std::vector<OpExecuteConfig>& candidateEngines)
103	{
104	    std::set<OpExecuteConfig> engineSet(candidateEngines.begin(), candidateEngines.end());
105	    for (int i = 0; i < cm.count; i++) {
106	        if (cm.costAlgoParams[i].algName == nullptr) {
107	            continue;
108	        }
109	        OpExecuteConfig engine = GetEngineByAlgName(cm.costAlgoParams[i].algName);
110	        if (engineSet.count(engine) == 0) {
111	            cm.costAlgoParams[i].count = 0;
112	        }
113	    }
114	    return HCCL_SUCCESS;
115	}
116	
117	HcclResult
118	SelectorEngine::InitCostModel(HcclComm comm, TopoInfoWithNetLayerDetails* topoInfo, OpParam& param, CostModel*& cm)
119	{
120	    HCCL_INFO("[SelectorEngine] Initializing costModel for comm, engine=%d.", static_cast<int>(param.opExecuteConfig));
121	
122	    // 全局一次性：构建算法名→3D 维度映射缓存
123	    static std::once_flag algoMapperFlag;
124	    std::call_once(algoMapperFlag, []() {
125	        AlgoNameMapper::Global()->Init(*GetAllAlgos());
126	    });
127	
128	    // 调用 CostModelManager 初始化，costModel 作为出参返回（局部变量，无线程安全问题）
129	    CostModelManager* costModelMgr = CostModelManager::Global();
130	    CostModel srcCm{nullptr, 0};
131	    CHK_RET(costModelMgr->InitCostModel(comm, topoInfo, srcCm));
132	
133	    // CostModel 含指针(costAlgoParams),分段拷贝: [CostModel header][CostAlgoParams array]
134	    void* ctxPtr = nullptr;
135	    uint64_t flatSize = sizeof(CostModel) + static_cast<uint64_t>(srcCm.count) * sizeof(CostAlgoParams);
136	    std::string costModelTag = std::string(COST_MODEL_TAG) + "_" + ENGINE_STR_MAP.at(param.opExecuteConfig);
137	    CHK_RET(HcclEngineCtxCreate(comm, costModelTag.c_str(), CommEngine::COMM_ENGINE_CPU, flatSize, &ctxPtr));
138	
139	    CostModel* storedCm = static_cast<CostModel*>(ctxPtr);
140	    storedCm->count = srcCm.count;
141	    storedCm->costAlgoParams = reinterpret_cast<CostAlgoParams*>(storedCm + 1);
142	    if (srcCm.count > 0 && srcCm.costAlgoParams != nullptr) {
143	        CHK_SAFETY_FUNC_RET(memcpy_s(
144	            storedCm->costAlgoParams, static_cast<uint64_t>(srcCm.count) * sizeof(CostAlgoParams), srcCm.costAlgoParams,
145	            static_cast<uint64_t>(srcCm.count) * sizeof(CostAlgoParams)));
146	    }
147	
148	    // 深拷贝 param 指针指向的内存，comm ctx 持有独立所有权
149	    for (int i = 0; i < storedCm->count; ++i) {
150	        int n = storedCm->costAlgoParams[i].count;
151	        const CostModelParam* srcParam = storedCm->costAlgoParams[i].param;
152	        if (n > 0 && srcParam != nullptr) {
153	            CostModelParam* owned = new (std::nothrow) CostModelParam[n];
154	            if (owned == nullptr) {
155	                HCCL_ERROR("[SelectorEngine] alloc param failed, i=%d count=%d.", i, n);
156	                return HcclResult::HCCL_E_PARA;
157	            }
158	            CHK_SAFETY_FUNC_RET(memcpy_s(
159	                owned, static_cast<uint64_t>(n) * sizeof(CostModelParam), srcParam,
160	                static_cast<uint64_t>(n) * sizeof(CostModelParam)));
161	            storedCm->costAlgoParams[i].param = owned;
162	        }
163	    }
164	
165	    // 释放临时 srcCm（comm ctx 已有独立深拷贝副本）
166	    CostModelManager::FreeCostModel(srcCm);
167	
168	    // 根据候选引擎过滤 costModel,再调用 algo 模块按 HCCL_ALGO 配置过滤
169	    std::vector<OpExecuteConfig> candidateEngines = GetEnginePriority(topoInfo, param.opExecuteConfig);
170	    CHK_RET(FilterCmByEngine(*storedCm, candidateEngines));
171	    std::vector<std::string> candidatePrefixes = CandidateEnginesToPrefixes(candidateEngines);
172	    CHK_RET(FilterCmByHcclAlgo(comm, *storedCm, candidatePrefixes));
173	
174	    cm = storedCm;
175	
176	    HCCL_INFO("[SelectorEngine] costModel initialized and stored in comm ctx, count=%d.", storedCm->count);
177	    return HCCL_SUCCESS;
178	}
179	
180	HcclResult
181	SelectorEngine::Run(HcclComm comm, OpParam& param, TopoInfoWithNetLayerDetails* topoInfo, std::string& algName)
182	{
183	    HCCL_INFO(
184	        "[SelectorEngine] Run start, opType=%d, opExecuteConfig=%d.", static_cast<int>(param.opType),
185	        static_cast<int>(param.opExecuteConfig));
186	
187	    // step 0: tuner 初始化（每通信域仅一次，独立于 costModel 引擎副本）
188	    void* tunerCtxPtr = nullptr;
189	    uint64_t tunerCtxSize = 0;
190	    if (HcclEngineCtxGet(comm, TUNER_INIT_TAG, CommEngine::COMM_ENGINE_CPU, &tunerCtxPtr, &tunerCtxSize)
191	        != HCCL_SUCCESS) {
192	        CHK_RET(HcclTunerInit(comm, topoInfo));
193	        CHK_RET(HcclEngineCtxCreate(comm, TUNER_INIT_TAG, CommEngine::COMM_ENGINE_CPU, 1, &tunerCtxPtr));
194	    }
195	
196	    // step 1: 从通信域 ctx 获取或初始化 costModel（按引擎区分 tag，回退时引擎变更会命中不同副本）
197	    CostModel* cm = nullptr;
198	    void* ctxPtr = nullptr;
199	    uint64_t ctxSize = 0;
200	    std::string costModelTag = std::string(COST_MODEL_TAG) + "_" + ENGINE_STR_MAP.at(param.opExecuteConfig);
201	    if (HcclEngineCtxGet(comm, costModelTag.c_str(), CommEngine::COMM_ENGINE_CPU, &ctxPtr, &ctxSize) == HCCL_SUCCESS) {
202	        cm = static_cast<CostModel*>(ctxPtr);
203	        HCCL_DEBUG("[SelectorEngine] costModel found in comm ctx, count=%d.", cm->count);
204	    } else {
205	        CHK_RET(InitCostModel(comm, topoInfo, param, cm));
206	    }
207	
208	    // step 2.1: 从 costModel 生成 costTable
209	    CostTable ct{nullptr, 0};
210	    CHK_RET(CostTableManager::Global()->CostTableGen(*cm, ct, topoInfo, param));
211	
212	    if (ct.count <= 0) {
213	        HCCL_WARNING("[SelectorEngine] costTable is empty after CostTableGen.");
214	    } else if (HcclTunerIsLoaded()) {
215	        // step 2.2: tuner（Enrich 填 3D 名 + 调用插件改 cost）
216	        AlgoNameMapper::Global()->Enrich(ct.costs, ct.count);
217	        bool tunerModified = false;
218	        CHK_RET(HcclTunerCallGetCollInfo(
219	            comm, param.opType, param.inputSize, param.DataDes.dataType, ct.costs, ct.count, &tunerModified));
220	        if (tunerModified) {
221	            HCCL_INFO("[SelectorEngine] tuner modified cost table.");
222	        } else {
223	            HCCL_INFO("[SelectorEngine] tuner did not modify cost table, using CostModel selection.");
224	        }
225	    }
226	
227	    // step 3: min(ct)
228	    HcclResult ret = SelectMinCost(ct, param, algName);
229	
230	    delete[] ct.costs;
231	    ct.costs = nullptr;
232	    ct.count = 0;
233	
234	    if (ret != HCCL_SUCCESS) {
235	        HCCL_ERROR("[SelectorEngine] Run failed, no algorithm selected.");
236	        return ret;
237	    }
238	
239	    HCCL_INFO(
240	        "[SelectorEngine] The opExecuteConfig is %s, the selected algo type is %s",
241	        ENGINE_STR_MAP.at(param.opExecuteConfig), algName.c_str());
242	    return HCCL_SUCCESS;
243	}
244	
245	HcclResult SelectorEngine::SelectMinCost(const CostTable& ct, OpParam& param, std::string& algName)
246	{
247	    // 遍历找最小 cost 并打印 costTable 明细, 格式: | idx | algName | engine | cost | status |
248	    HCCL_INFO(
249	        "[SelectorEngine] SelectMinCost: costTable count=%d, opType=%d, dataSize=%llu.", ct.count,
250	        static_cast<int>(param.opType), param.inputSize);
251	    HCCL_INFO("[SelectorEngine] +-----+----------------------------------+----------+--------------+----------+");
252	    HCCL_INFO("[SelectorEngine] | idx | algName                          | engine   | cost         | status   |");
253	    HCCL_INFO("[SelectorEngine] +-----+----------------------------------+----------+--------------+----------+");
254	    int minIdx = -1;
255	    float minCost = 0.0f;
256	    std::vector<std::string> tiedAlgos;
257	    for (int i = 0; i < ct.count; ++i) {
258	        const char* name = ct.costs[i].algName;
259	        float cost = ct.costs[i].cost;
260	        std::string status = (name == nullptr || cost < 0.0f) ? "filtered" : "valid";
261	        std::string engineStr = name == nullptr ? "-" : ENGINE_STR_MAP.at(GetEngineByAlgName(name));
262	        std::string nameStr = name != nullptr ? name : "-";
263	        char costBuf[32];
264	        const char* fmt = (cost >= 0.0f && cost < 1.0f) ? "%.6f" : "%.2f";
265	        int costRet = sprintf_s(costBuf, sizeof(costBuf), fmt, cost);
266	        if (costRet < 0) {
267	            HCCL_ERROR("[SelectorEngine] SelectMinCost: sprintf_s failed.");
268	            return HCCL_E_INTERNAL;
269	        }
270	        HCCL_INFO(
271	            "[SelectorEngine] | %3d | %-32s | %-8s | %12s | %-8s |", i, nameStr.substr(0, 32).c_str(),
272	            engineStr.substr(0, 8).c_str(), costBuf, status.c_str());
273	
274	        if (name == nullptr || cost < 0.0f) {
275	            continue;
276	        }
277	        if (minIdx == -1 || cost < minCost) {
278	            minIdx = i;
279	            minCost = cost;
280	            tiedAlgos.clear();
281	            tiedAlgos.emplace_back(name);
282	        } else if (cost == minCost) {
283	            tiedAlgos.emplace_back(name);
284	        }
285	    }
286	    HCCL_INFO("[SelectorEngine] +-----+----------------------------------+----------+--------------+----------+");
287	
288	    if (minIdx < 0) {
289	        HCCL_ERROR(
290	            "[SelectorEngine] SelectMinCost: no valid algorithm found, expansionMode=%d, costTable count=%d.",
291	            static_cast<int>(param.commOpExpansionMode), ct.count);
292	        return HCCL_E_NOT_SUPPORT;
293	    }
294	
295	    if (tiedAlgos.size() > 1) {
296	        std::string algoNames;
297	        for (size_t i = 0; i < tiedAlgos.size(); ++i) {
298	            if (i > 0) {
299	                algoNames += ", ";
300	            }
301	            algoNames += tiedAlgos[i];
302	        }
303	        HCCL_WARNING(
304	            "[SelectorEngine] multiple algos with same cost=%f: [%s], selecting %s.", minCost, algoNames.c_str(),
305	            tiedAlgos[0].c_str());
306	    }
307	
308	    algName = ct.costs[minIdx].algName;
309	    param.opExecuteConfig = GetEngineByAlgName(algName);
310	    HCCL_INFO(
311	        "[SelectorEngine] SelectMinCost: selected algName=%s, engine=%s, cost=%f.", algName.c_str(),
312	        ENGINE_STR_MAP.at(param.opExecuteConfig), minCost);
313	    return HCCL_SUCCESS;
314	}
315	
316	} // namespace ops_hccl
